   192  /// Convert a string to a signed integer, with overflow detection
   193  /** @param[in]  in     Input string
   194      @param[out] end    Returned end pointer
   195      @param[in]  bits   Bits available for the converted value
   196      @param[out] failed Location of overflow flag
   197      @return String value converted to an int64_t
   198
   199  Converts a signed decimal string to an int64_t.  The string should
   200  consist of an optional '+' or '-' sign followed by one or more of
   201  the digits 0 to 9.  The output value will be limited to fit in the
   202  given number of bits (including the sign bit).  If the value is too big,
   203  the largest possible value will be returned and *failed will be set to 1.
   204
   205  The address of the first character following the converted number will
   206  be stored in *end.
   207
   208  Both end and failed must be non-NULL.
   209   */
   210  static inline int64_t hts_str2int(const char *in, char **end, int bits,
   211                                      int *failed) {
   212      uint64_t n = 0, limit = (1ULL << (bits - 1)) - 1;
   213      uint32_t fast = (bits - 1) * 1000 / 3322 + 1; // log(10)/log(2) ~= 3.322
   214      const unsigned char *v = (const unsigned char *) in;
   215      const unsigned int ascii_zero = '0'; // Prevents conversion to signed
   216      unsigned char d;
   217      int neg = 1;
   218
   219      switch(*v) {
   220      case '-':
   221          neg=-1;
   222          limit++; /* fall through */
   223      case '+':
   224          v++;
   225          break;
   226      default:
   227          break;
   228      }
   229
   230      while (--fast && *v>='0' && *v<='9')
   231          n = n*10 + *v++ - ascii_zero;
   232
   233      if (!fast) {
   234          uint64_t limit_d_10 = limit / 10;
   235          uint64_t limit_m_10 = limit - 10 * limit_d_10;
   236           while ((d = *v - ascii_zero) < 10) {
   237              if (n < limit_d_10 || (n == limit_d_10 && d <= limit_m_10)) {
   238                  n = n*10 + d;
   239                  v++;
   240              } else {
   241                  do { v++; } while (*v - ascii_zero < 10);
   242                  n = limit;
   243                  *failed = 1;
   244                  break;
   245              }
   246          }
   247      }
   248
   249      *end = (char *)v;
   250
   251      return (n && neg < 0) ? -((int64_t) (n - 1)) - 1 : (int64_t) n;
   252  }
